using System.ComponentModel;

namespace ElegantSeries.Flow.Routing;

/// <summary>
/// Marks an assembly as containing view registrations generated by the
/// ElegantSeries.Flow source generator (a <c>ViewForRegistrations</c> class
/// in the assembly's generated namespace — by default
/// <c>ElegantSeries.Flow.Generated.&lt;assembly name&gt;</c>, with a fixed
/// <c>Unknown</c> segment in place of the assembly name when the assembly
/// has no name, or the namespace set with
/// <see cref="ViewForGeneratedNamespaceAttribute"/>).
/// </summary>
/// <remarks>
/// <para>
/// This attribute is emitted by the source generator into the generated
/// registrations file; it is never written by hand. Its presence is how the
/// generator, when compiling an assembly that references this one,
/// recognizes the referenced assembly as a view-registration provider and
/// includes it in the <c>RegisterAllAttributedViews</c> aggregation.
/// </para>
/// <para>
/// The form taking a string records the full name of the generated
/// registrations type, so a consuming compilation reads the location from
/// the marker instead of deriving it from the assembly name. Markers
/// emitted by older generator versions carry no name; consumers then fall
/// back to deriving the location from the assembly name. The marker has no
/// runtime effect; it is a compile-time marker only.
/// </para>
/// </remarks>
[AttributeUsage(AttributeTargets.Assembly, AllowMultiple = false, Inherited = false)]
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed class GeneratedViewRegistrationsAttribute : Attribute
{
    /// <summary>
    /// Initializes a marker that carries no registrations type name
    /// (the form emitted by older generator versions).
    /// </summary>
    public GeneratedViewRegistrationsAttribute()
    {
    }

    /// <summary>
    /// Initializes a marker that records the full name of the generated
    /// <c>ViewForRegistrations</c> type in the marked assembly.
    /// </summary>
    /// <param name="registrationsTypeFullName">
    /// The full name of the generated registrations type.
    /// </param>
    public GeneratedViewRegistrationsAttribute(string registrationsTypeFullName)
    {
        RegistrationsTypeFullName = registrationsTypeFullName;
    }

    /// <summary>
    /// Gets the full name of the generated registrations type recorded by
    /// this marker, or <see langword="null"/> when the marker carries none.
    /// </summary>
    public string? RegistrationsTypeFullName { get; }
}
